<script setup>
import {ref,computed,onMounted} from 'vue'
import {Plus, X, Check, RefreshCw, AlertCircle, ClipboardList, Search, Eye, ChevronDown} from 'lucide-vue-next'
const props=defineProps({request:{type:Function,required:true}})
const emit=defineEmits(['changed'])
const solicitudes=ref([]),equipos=ref([]),departamentos=ref([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),creating=ref(false),query=ref(''),numero=ref(''),observaciones=ref(''),departamento=ref(''),selected=ref([]),filtro=ref(''),filtroEstado=ref(''),detalleId=ref(null)
const filteredEquipos=computed(()=>equipos.value.filter(e=>String(e.departamento)===String(departamento.value)).filter(e=>`${e.no_inventario} ${e.marca} ${e.modelo}`.toLowerCase().includes(query.value.toLowerCase())))
const deptosDisponibles=computed(()=>departamentos.value)
const estados=computed(()=>[...new Set(solicitudes.value.map(s=>s.estado).filter(Boolean))].sort())
const filtradas=computed(()=>solicitudes.value.filter(s=>{
 const coincideTexto=[s.numero,s.solicitante_nombre,s.departamento_nombre,s.estado].some(v=>String(v??'').toLowerCase().includes(filtro.value.trim().toLowerCase()))
 return coincideTexto&&(!filtroEstado.value||s.estado===filtroEstado.value)
}))
const detalle=computed(()=>solicitudes.value.find(s=>s.id===detalleId.value)||null)
function formatoFecha(fecha){if(!fecha)return '—';const d=new Date(fecha);return Number.isNaN(d.getTime())?'—':d.toLocaleString('es-CU')}
function valor(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='object')return v.nombre||v.no_inventario||v.numero||v.id||'—';return String(v)}
function nombreEquipo(item){const id=item?.equipo?.id??item?.equipo??item?.id;const e=equipos.value.find(x=>String(x.id)===String(id));return e?.no_inventario||item?.no_inventario||`Equipo #${id??'—'}`}

function parseRows(v){return Array.isArray(v)?v:Array.isArray(v?.results)?v.results:Array.isArray(v?.datos)?v.datos:[]}
function message(e){if(e?.message)return e.message;return 'No se pudo completar la operación.'}
async function reload(){
 loading.value=true;error.value=''
 try{
  const [s,e,d]=await Promise.allSettled([
   props.request('/api/solicitudes/'),
   props.request('/api/equipos/'),
   props.request('/api/departamentos/')
  ])
  solicitudes.value=s.status==='fulfilled'?parseRows(s.value):[]
  if(detalleId.value!==null&&!solicitudes.value.some(x=>x.id===detalleId.value))detalleId.value=null
  equipos.value=e.status==='fulfilled'?parseRows(e.value):[]
  departamentos.value=d.status==='fulfilled'?parseRows(d.value):[]
  const failures=[]
  if(s.status==='rejected')failures.push('solicitudes: '+message(s.reason))
  if(e.status==='rejected')failures.push('equipos: '+message(e.reason))
  if(d.status==='rejected')failures.push('departamentos: '+message(d.reason))
  if(failures.length)error.value='No se pudieron cargar algunos datos ('+failures.join('; ')+').'
 }finally{loading.value=false}
}
onMounted(reload)
function start(){numero.value='';observaciones.value='';departamento.value='';selected.value=[];query.value='';error.value='';success.value='';creating.value=true}
function toggle(id){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
function changeDept(){selected.value=[]}
function csrf(){const match=document.cookie.split('; ').find(c=>c.startsWith('csrftoken='));return match?decodeURIComponent(match.slice('csrftoken='.length)):''}
async function submit(){error.value='';success.value='';if(!numero.value.trim()||!departamento.value||!selected.value.length){error.value='Introduce el número, selecciona un departamento y al menos un equipo.';return}saving.value=true;try{await props.request('/api/csrf/');await props.request('/api/solicitudes/',{method:'POST',headers:{'Content-Type':'application/json','X-CSRFToken':csrf()},body:JSON.stringify({numero:numero.value.trim(),observaciones:observaciones.value,equipos:selected.value})});creating.value=false;success.value='Solicitud creada en borrador correctamente.';await reload();emit('changed')}catch(e){error.value=message(e)}finally{saving.value=false}}
</script>
<template>
<section class="solicitudes-modulo">
 <div class="sol-head"><div><h3>Solicitudes de baja</h3><p>Registra equipos de un mismo departamento y consulta las solicitudes existentes.</p></div><div class="sol-actions"><button class="secondary" type="button" @click="reload"><RefreshCw :size="15"/> Actualizar</button><button v-if="!creating" class="primary" type="button" @click="start"><Plus :size="16"/> Nueva solicitud</button></div></div>
 <div v-if="error" class="sol-alert error" role="alert"><AlertCircle :size="17"/> {{error}}</div><div v-if="success" class="sol-alert success" role="status"><Check :size="17"/> {{success}}</div>
 <form v-if="creating" class="sol-form" @submit.prevent="submit"><div class="sol-form-title"><h4>Nueva solicitud de baja</h4><button type="button" class="sol-close" aria-label="Cerrar formulario" @click="creating=false"><X :size="20"/></button></div>
 <div class="sol-fields"><label>Número de solicitud <span>*</span><input v-model="numero" required maxlength="100" placeholder="Ej.: BAJA-2026-001"/></label><label>Departamento de origen <span>*</span><select v-model="departamento" required @change="changeDept"><option value="">Selecciona un departamento</option><option v-for="d in deptosDisponibles" :key="d.id" :value="d.id">{{d.nombre}} · {{d.sede_nombre||'Sede no especificada'}}</option></select><small v-if="!loading && !departamentos.length" class="sol-hint">No hay departamentos disponibles. Comprueba la API de departamentos o tus permisos.</small></label></div>
 <label class="sol-full-label">Observaciones<textarea v-model="observaciones" rows="3" placeholder="Motivo y observaciones de la solicitud"></textarea></label>
 <div class="sol-equipment"><div class="sol-equipment-header"><strong>Equipos a dar de baja <span>*</span></strong><small>{{selected.length}} seleccionados</small></div><input v-model="query" type="search" placeholder="Buscar por inventario, marca o modelo…" :disabled="!departamento" aria-label="Buscar equipos"/><div v-if="!departamento" class="sol-hint">Primero selecciona un departamento.</div><div v-else-if="!filteredEquipos.length" class="sol-hint">No hay equipos registrados en este departamento que coincidan con la búsqueda. Puedes registrar un equipo desde el administrador de Django.</div><div v-else class="sol-equipment-list"><label v-for="e in filteredEquipos" :key="e.id" class="sol-equipment-row"><input type="checkbox" :checked="selected.includes(e.id)" @change="toggle(e.id)"/><span><strong>{{e.no_inventario}}</strong><small>{{e.tipo_recurso_nombre||'Equipo'}} · {{e.marca||'Sin marca'}} {{e.modelo||''}}</small></span></label></div></div>
 <p class="sol-hint">La API valida que los equipos pertenezcan al mismo departamento y que tengas permiso para crear la solicitud. La importación desde Excel aún no está disponible en esta pantalla.</p><div class="sol-form-actions"><button type="button" class="secondary" @click="creating=false">Cancelar</button><button class="primary" type="submit" :disabled="saving||!selected.length">{{saving?'Guardando…':'Guardar solicitud'}}</button></div></form>
 <div class="sol-table-header"><h4>Solicitudes registradas</h4><span>{{filtradas.length}} de {{solicitudes.length}} registros</span></div>
 <div class="sol-filters"><label class="sol-search"><Search :size="16"/><input v-model="filtro" type="search" placeholder="Buscar por número, solicitante o departamento…" aria-label="Buscar solicitudes"/></label><label class="sol-status"><span>Estado</span><select v-model="filtroEstado" aria-label="Filtrar por estado"><option value="">Todos</option><option v-for="estado in estados" :key="estado" :value="estado">{{estado}}</option></select><ChevronDown :size="15"/></label></div>
 <div v-if="loading" class="sol-hint sol-loading">Cargando datos…</div>
 <div v-else-if="!filtradas.length" class="sol-empty"><ClipboardList :size="30"/><strong>{{solicitudes.length?'No hay coincidencias':'Sin solicitudes registradas'}}</strong><p>{{solicitudes.length?'Prueba con otros filtros.':'Utiliza «Nueva solicitud» para crear el primer registro, si tu rol lo permite.'}}</p></div>
 <div v-else class="table-scroll"><table><thead><tr><th>Número</th><th>Estado</th><th>Solicitante</th><th>Equipos</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody><tr v-for="s in filtradas" :key="s.id"><td><strong>{{s.numero}}</strong></td><td><span class="state-pill">{{s.estado}}</span></td><td>{{s.solicitante_nombre||'—'}}</td><td>{{s.equipos_asociados?.length??'—'}}</td><td>{{s.fecha_creacion?new Date(s.fecha_creacion).toLocaleDateString('es-CU'):'—'}}</td><td><button class="sol-detail-button" type="button" @click="detalleId=detalleId===s.id?null:s.id"><Eye :size="15"/> {{detalleId===s.id?'Ocultar':'Ver detalles'}}</button></td></tr></tbody></table></div>
 <div v-if="detalle" class="sol-detail"><div class="sol-detail-head"><div><small>DETALLE DE SOLICITUD</small><h4>{{detalle.numero}}</h4></div><button class="sol-close" type="button" aria-label="Cerrar detalle" @click="detalleId=null"><X :size="19"/></button></div><div class="sol-detail-grid"><div><small>Estado</small><strong>{{valor(detalle.estado)}}</strong></div><div><small>Solicitante</small><strong>{{valor(detalle.solicitante_nombre)}}</strong></div><div><small>Departamento</small><strong>{{valor(detalle.departamento_nombre??detalle.departamento)}}</strong></div><div><small>Fecha de creación</small><strong>{{formatoFecha(detalle.fecha_creacion)}}</strong></div></div><div class="sol-detail-block"><small>Observaciones</small><p>{{detalle.observaciones||'Sin observaciones registradas.'}}</p></div><div class="sol-detail-block"><small>Equipos asociados</small><ul v-if="detalle.equipos_asociados?.length"><li v-for="(item,i) in detalle.equipos_asociados" :key="item.id??i">{{nombreEquipo(item)}}</li></ul><p v-else>El listado no incluye el detalle de los equipos asociados.</p></div><p class="sol-hint">Información mostrada según los campos disponibles en la API. Las decisiones de aprobación se gestionarán al verificar los permisos del backend.</p></div>
 </section>
</template>
<style scoped>
