t-size:12px;color:#25465f}.sol-equipment-row small{font-size:11px;color:#8094a6}.sol-hint{font-size:12px;color:#8094a6;line-height:1.6}.sol-form-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}.sol-table-header{display:flex;justify-content:space-between;align-items:center;padding:20px 24px}.sol-table-header h4{margin:0;font-size:14px;color:#25425c}.sol-table-header span{font-size:11px;color:#8a9db0}.sol-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:48px 20px;color:#89a0b4;gap:9px}.sol-empty strong{color:#4b657d;font-size:13px}.sol-empty p{font-size:12px;margin:0;text-align:center}.sol-loading{padding:24px}@media(max-width:800px){.sol-head{flex-direction:column;align-items:flex-start}.sol-fields{grid-template-columns:1fr}.sol-form{margin:14px;padding:16px}.sol-head{padding:18px}}
